package com.arshad.ayn.core.access

/**
 * One of a video's caption tracks as YouTube lists it (M7-D14).
 *
 * @property languageTag YouTube's language code for the track ("en", "de-DE", "es-419").
 * @property name YouTube's own label ("English", "English (auto-generated)"), so two tracks in one
 *   language stay apart; the language's own name when YouTube gives none.
 * @property autoGenerated made by YouTube's speech recognition.
 * @property url the track's TTML on YouTube's timedtext endpoint: signed, bound to the IP that
 *   resolved the video, and expiring, so only that device fetches it, while it is fresh.
 */
data class CaptionTrack(
    val languageTag: String,
    val name: String,
    val autoGenerated: Boolean,
    val url: String,
)

/** One caption shown from [startMs] until [endMs]; [text]'s lines are joined by `\n`. */
data class CaptionCue(val startMs: Long, val endMs: Long, val text: String) {
    init {
        require(endMs > startMs) { "a cue ends after it starts" }
    }
}

/**
 * Captions seam (M7-D14): one track's cues, fetched and parsed. Main-safe; never throws for a
 * network, server or parse problem, which comes back as [CaptionLookup.Failed].
 */
fun interface CaptionSource {
    suspend fun cues(track: CaptionTrack): CaptionLookup
}

sealed interface CaptionLookup {
    /** In time order, never overlapping; empty when the track has no text. */
    data class Found(val cues: List<CaptionCue>) : CaptionLookup

    /** Couldn't be fetched (network, rate limit, an expired link) or read. */
    data object Failed : CaptionLookup
}
